(24, 24, 'شصسثقیفبغ', 23456.00, 3456.00, 'img_6aa4141f502ce7.89227551.png', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-11 14:45:51'),
(25, 25, 'دوربین بدون آینه کانن Canon EOS R6 V Mirrorless Camera', 488000000.00, 888000000.00, 'img_6aa4150a111084.46625769.png', 'img_6aa4150a1172e1.50951736.png', 'img_6aa4150a11bb19.90309683.png', 'img_6aa4150a122d08.02643730.png', 'img_6aa4150a127481.68821299.png', '<h3>معرفی دوربین کنون Canon EOS R6 V؛ ترکیبی از قدرت سینمایی و انعطاف پذیری حرفه ای</h3><p>دوربین بدون آینه کانن Canon EOS R6 V Mirrorless Camera یکی از جدیدترین محصولات کانن است که با تمرکز ویژه بر تولید محتوا، فیلم سازی حرفه ای و پروژه های ویدیویی طراحی شده است. این دوربین کانن با بهره گیری از فناوری های پیشرفته سری Cinema EOS و امکانات قدرتمند سری EOS R، انتخابی فوق العاده برای فیلم سازان، ولاگرها، یوتیوبرها و تولیدکنندگان محتوای حرفه ای به شمار می رود.</p><p>اگر به دنبال دوربینی هستید که بتواند علاوه بر ثبت عکس های باکیفیت، قابلیت های سینمایی پیشرفته نیز در اختیار شما قرار دهد، Canon EOS R6 V یکی از جذاب ترین گزینه های موجود در بازار محسوب می شود. در فروشگاه دیجی 24 می توانید این دوربین حرفه ای را با ضمانت اصالت کالا و خدمات معتبر تهیه کنید.</p><figure class=\"image\"><img style=\"aspect-ratio:1536/1024;\" src=\"/project%20-php/up/content_6aa414f07f726.jpg\" width=\"1536\" height=\"1024\"></figure>', NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-11 14:49:46'),
